/// <summary>
/// This is a UI builder class for CPI repricing batch job.
/// </summary>
class METCPIRepricingUIBuilder  extends SysOperationAutomaticUIBuilder
{
    private METCPIRepricingContract contract;
    private DialogField inventSiteIdDialogField;


}

Method.Source:
/// <summary>
/// Overrides the method to add custom logic.
/// </summary>
public void postBuild()
{
    super();

    contract = this.dataContractObject() as METCPIRepricingContract;

    inventSiteIdDialogField = this.bindInfo().getDialogField(contract, methodStr(METCPIRepricingContract, parminventSiteIdList));

    inventSiteIdDialogField.lookupButton(FormLookupButton::Always);
}

/// <summary>
/// Overriden postRun method.
/// </summary>
public void postRun()
{
    this.constructItemIdLookup();
}

/// <summary>
/// Constructs item Id multiselect lookup.
/// </summary>
private void constructItemIdLookup()
{
    Query		         query;
    QueryBuildDataSource qbds;

    query = new Query();
    qbds  = query.addDataSource(tablenum(InventSite));

    qbds.fields().addField(fieldNum(InventSite, SiteId));

    container selectedFields = [tableNum(InventSite), fieldNum(InventSite, SiteId)];

    SysLookupMultiSelectCtrl::constructWithQuery(this.dialog().dialogForm().formRun(), inventSiteIdDialogField.control(), query, false, selectedFields);
}
